-- ============================================================================
-- G. VIEWS
-- ============================================================================
-- Lookup of view types. wire_code PROVEN (client enum); is_task_view marks types that use the shared query block.
CREATE TABLE view_types (
  key           text PRIMARY KEY,
  wire_code     smallint NOT NULL UNIQUE,
  is_task_view  boolean NOT NULL
);

INSERT INTO view_types (key, wire_code, is_task_view) VALUES
  ('list',1,true),('board',2,true),('box',3,true),('calendar',5,true),('embed',6,false),('gantt',7,true),
  ('doc',9,false),('form',15,false),('timeline',16,true),('activity',17,false),('workload',18,true),
  ('mindmap',20,true),('table',23,true),('map',26,true),('whiteboard',27,false),('dashboard',29,false),
  ('gallery',35,true);

CREATE TABLE views (
  id               uuid PRIMARY KEY,
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  view_type        text NOT NULL REFERENCES view_types(key),
  container_id     uuid /* id -> hierarchy.containers */,   -- NULL = workspace-level ("Everything") view. PROVEN parent codes incl. workspace
  name             text NOT NULL,
  visibility       text NOT NULL DEFAULT 'public' CHECK (visibility IN ('public','private','protected')), -- PROVEN public=1, private=2; protected ASSUMED
  owner_id         uuid /* id -> identity.users */,
  is_default       boolean NOT NULL DEFAULT false,       -- PROVEN
  auto_save        boolean NOT NULL DEFAULT false,       -- PROVEN
  show_in_sidebar  boolean NOT NULL DEFAULT false,       -- PROVEN sidebar_view
  position         text NOT NULL COLLATE "C",            -- tab order (PROVEN sidebar_orderindex int)
  settings_schema  smallint NOT NULL DEFAULT 1,
  settings         jsonb NOT NULL DEFAULT '{}',          -- PER-TYPE block only (calendar, gantt, timeline, workload, table, box...). PROVEN one block per type
  public_token_hash text,                                -- public share link. ASSUMED storage; PROVEN expiry field public_share_expires_on
  public_expires_at timestamptz,
  created_by       uuid /* id -> identity.users */,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  version          integer NOT NULL DEFAULT 1
);

-- Tabs of a container, in order. Workspace-level views have NULL container_id and sort first (use IS NOT DISTINCT in queries).
CREATE INDEX views_container_idx ON views (workspace_id, container_id, position) WHERE deleted_at IS NULL;

CREATE INDEX views_owner_idx ON views (workspace_id, owner_id) WHERE deleted_at IS NULL AND visibility = 'private';

CREATE UNIQUE INDEX views_public_token_uk ON views (public_token_hash) WHERE public_token_hash IS NOT NULL;

CREATE UNIQUE INDEX views_default_uk ON views (workspace_id, container_id, view_type) WHERE is_default AND deleted_at IS NULL AND container_id IS NOT NULL;

-- Shared query block: filters, grouping, subgrouping, search. One row per task-type view. PROVEN fields
-- (filters {search, show_closed, op, filter_groups[], fields[]}, grouping {field,dir,collapsed,ignore}, sorting {fields[]}).
CREATE TABLE view_queries (
  view_id            uuid PRIMARY KEY REFERENCES views(id) ON DELETE CASCADE,
  workspace_id       uuid NOT NULL /* id -> access.workspaces */,
  search_text        text,
  show_closed        boolean NOT NULL DEFAULT false,
  show_subtasks      text NOT NULL DEFAULT 'collapsed' CHECK (show_subtasks IN ('hidden','collapsed','expanded','separate')),  -- ASSUMED values
  filter_op          text NOT NULL DEFAULT 'AND' CHECK (filter_op IN ('AND','OR')),
  filter_tree        jsonb NOT NULL DEFAULT '{"groups":[]}',  -- nested conditions; evaluated by the query engine, never joined/filtered in SQL. ASSUMED
  group_by_key       text DEFAULT 'status',                   -- built-in key: status, assignee, priority, due_date, tag, task_type, none ...
  group_by_field_id  uuid /* id -> tasks.custom_fields */,       -- or a custom field (exactly one of key/field)
  group_dir          smallint NOT NULL DEFAULT 1 CHECK (group_dir IN (1,-1)),
  group_ignore_empty boolean NOT NULL DEFAULT false,
  updated_at         timestamptz NOT NULL DEFAULT now(),
  version            integer NOT NULL DEFAULT 1,
  CHECK (num_nonnulls(group_by_key, group_by_field_id) = 1)
);

CREATE INDEX view_queries_ws_idx ON view_queries (workspace_id, view_id);

-- "Which views break if custom field F is deleted".
CREATE INDEX view_queries_group_field_idx ON view_queries (workspace_id, group_by_field_id) WHERE group_by_field_id IS NOT NULL;

CREATE TABLE view_sorts (
  view_id        uuid NOT NULL REFERENCES views(id) ON DELETE CASCADE,
  workspace_id   uuid NOT NULL /* id -> access.workspaces */,
  rank           smallint NOT NULL,
  field_key      text,                                    -- built-in key (due_date, priority, name, manual ...)
  custom_field_id uuid /* id -> tasks.custom_fields */,
  direction      smallint NOT NULL DEFAULT 1 CHECK (direction IN (1,-1)),
  PRIMARY KEY (view_id, rank),
  CHECK (num_nonnulls(field_key, custom_field_id) = 1)
);

CREATE INDEX view_sorts_field_idx ON view_sorts (workspace_id, custom_field_id) WHERE custom_field_id IS NOT NULL;

-- Visible columns for list/table views (PROVEN view_columns: field, pinned, hidden, position).
CREATE TABLE view_columns (
  view_id        uuid NOT NULL REFERENCES views(id) ON DELETE CASCADE,
  workspace_id   uuid NOT NULL /* id -> access.workspaces */,
  position       text NOT NULL COLLATE "C",
  field_key      text,
  custom_field_id uuid /* id -> tasks.custom_fields */,
  pinned         boolean NOT NULL DEFAULT false,
  hidden         boolean NOT NULL DEFAULT false,
  width_px       smallint,
  id             uuid PRIMARY KEY,
  CHECK (num_nonnulls(field_key, custom_field_id) = 1)
);

CREATE INDEX view_columns_view_idx ON view_columns (view_id, position);

CREATE UNIQUE INDEX view_columns_key_uk ON view_columns (view_id, field_key) WHERE field_key IS NOT NULL;

CREATE UNIQUE INDEX view_columns_cf_uk  ON view_columns (view_id, custom_field_id) WHERE custom_field_id IS NOT NULL;

-- Board config incl. swimlanes. PROVEN swimlanes {enabled, divide, collapsed, field}.
CREATE TABLE view_board_config (
  view_id          uuid PRIMARY KEY REFERENCES views(id) ON DELETE CASCADE,
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  swimlanes_enabled boolean NOT NULL DEFAULT false,
  swimlane_key     text,
  swimlane_field_id uuid /* id -> tasks.custom_fields */,
  swimlane_dir     smallint NOT NULL DEFAULT 1 CHECK (swimlane_dir IN (1,-1)),
  card_size        text NOT NULL DEFAULT 'medium' CHECK (card_size IN ('small','medium','large')),  -- ASSUMED
  updated_at       timestamptz NOT NULL DEFAULT now(),
  version          integer NOT NULL DEFAULT 1,
  CHECK (NOT swimlanes_enabled OR num_nonnulls(swimlane_key, swimlane_field_id) = 1),
  CHECK (num_nonnulls(swimlane_key, swimlane_field_id) <= 1)
);

-- Collapsed columns / swimlanes / groups (PROVEN collapsed arrays), as rows so a group can be un-collapsed by id.
CREATE TABLE view_collapsed_groups (
  view_id       uuid NOT NULL REFERENCES views(id) ON DELETE CASCADE,
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  axis          text NOT NULL CHECK (axis IN ('group','swimlane')),
  group_key     text NOT NULL,                              -- status id, option id, user id, or '__none__'
  PRIMARY KEY (view_id, axis, group_key)
);

-- Sharing / visibility: who a private or protected view is shared with (PROVEN view_members).
CREATE TABLE view_shares (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  view_id       uuid NOT NULL REFERENCES views(id) ON DELETE CASCADE,
  user_id       uuid /* id -> identity.users */,
  group_id      uuid /* id -> access.user_groups */,
  permission    text NOT NULL DEFAULT 'view' CHECK (permission IN ('view','edit')),   -- ASSUMED
  created_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (num_nonnulls(user_id, group_id) = 1)
);

CREATE UNIQUE INDEX view_shares_user_uk  ON view_shares (view_id, user_id)  WHERE user_id IS NOT NULL;

CREATE UNIQUE INDEX view_shares_group_uk ON view_shares (view_id, group_id) WHERE group_id IS NOT NULL;

CREATE INDEX view_shares_user_idx ON view_shares (workspace_id, user_id, view_id) WHERE user_id IS NOT NULL;

-- SEC-007
ALTER TABLE view_shares ADD COLUMN expires_at timestamptz;

CREATE TABLE export_jobs (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  kind text NOT NULL CHECK (kind IN ('tenant','view','dashboard','audit','time','user_data')),
  format text NOT NULL CHECK (format IN ('json','csv','pdf','png')),
  scope jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','ready','failed','expired')),
  file_id uuid /* id -> files.files */, expires_at timestamptz,
  requested_by uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz
);

-- Channel access: project channel members = users who can read the container (derive via container_user_caps), not stored.

