-- 14. NAVIGATION conveniences  (FR-221, FR-223, FRD 7.4)
-- =============================================================================
CREATE TABLE user_favorites (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  object_type text NOT NULL, object_id uuid NOT NULL, position text NOT NULL COLLATE "C",
  PRIMARY KEY (workspace_id, user_id, object_type, object_id)
);

CREATE TABLE user_recents (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  object_type text NOT NULL, object_id uuid NOT NULL, visited_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, user_id, object_type, object_id)
);

CREATE INDEX user_recents_time ON user_recents (workspace_id, user_id, visited_at DESC);
